    await page.waitForTimeout(500);

    // Verify dialog is closed by default
    const isDialogClosed = await page.evaluate(() => {
        const dialog = document.getElementById('delete-confirm-dialog');
        return !dialog.open;
    });
    console.log(`✓ Dialog closed by default: ${isDialogClosed}`);

    // Verify trigger has correct class
    const triggerClassCorrect = await page.evaluate(() => {
        const triggers = document.querySelectorAll('.trigger');
        return triggers.length > 0;
    });
    console.log(`✓ Trigger elements found: ${triggerClassCorrect}`);

