2.     const dialog = document.getElementById('delete-confirm-dialog');
3.     const triggers = document.querySelectorAll('.trigger');
4.     let currentTrigger = null;
5.     let currentImageId = null;
6. 
7.     // Open dialog when delete button is clicked
8.     triggers.forEach(trigger => {
9.         trigger.addEventListener('click', () => {
10.             currentTrigger = trigger;
11.             currentImageId = trigger.dataset.image;
12.             dialog.showModal();
13.         });
14.     });
15. 
16.     // Handle cancel button
17.     dialog.querySelector('[data-action="cancel"]').addEventListener('click', () => {
18.         dialog.close('cancel');
19.     });
20. 
21.     // Handle delete button
22.     dialog.querySelector('[data-action="delete"]').addEventListener('click', () => {
23.         dialog.close('delete');
24.     });
