 document.addEventListener('DOMContentLoaded', () => {
     const dialog = document.getElementById('delete-confirm-dialog');
     const triggers = document.querySelectorAll('.trigger');
     let currentTrigger = null;
     let currentImageId = null;

     // Open dialog when delete button is clicked
     triggers.forEach(trigger => {
         trigger.addEventListener('click', () => {
             currentTrigger = trigger;
             currentImageId = trigger.dataset.image;
             dialog.showModal();
         });
     });

     // Handle cancel button
     dialog.querySelector('[data-action="cancel"]').addEventListener('click', () => {
         dialog.close('cancel');
     });

     // Handle delete button
     dialog.querySelector('[data-action="delete"]').addEventListener('click', () => {
         dialog.close('delete');
     });

     // Handle dialog close
     dialog.addEventListener('close', () => {
         if (dialog.returnValue === 'delete') {
             handleImageDeletion(currentImageId);
         }
         currentTrigger = null;
         currentImageId = null;
     });

     // Handle Escape key (browser does this automatically, but we handle it explicitly for safety)
     dialog.addEventListener('cancel', () => {
         dialog.close('cancel');
     });
 });

 function handleImageDeletion(imageId) {
     const imageCard = document.querySelector(`button[data-image="${imageId}"]`)?.closest('.image-card');

     if (imageCard) {
         // Add fade-out animation
         imageCard.style.animation = 'fadeOut 0.3s ease forwards';

         // Remove card from DOM after animation completes
         setTimeout(() => {
             imageCard.remove();
             showSuccessMessage();
         }, 300);
     }
 }

 function showSuccessMessage() {
     const message = document.createElement('div');
     message.setAttribute('role', 'status');
     message.setAttribute('aria-live', 'polite');
     message.className = 'success-message';
     message.textContent = 'Image deleted successfully.';

     document.body.appendChild(message);

     // Remove message after 3 seconds
     setTimeout(() => {
         message.remove();
     }, 3000);
 }

 // Add fade-out animation to stylesheet if it doesn't exist
 if (!document.querySelector('style[data-anim-fadeout]')) {
     const style = document.createElement('style');
     style.setAttribute('data-anim-fadeout', 'true');
     style.textContent = `
         @keyframes fadeOut {
             from {
                 opacity: 1;
                 transform: translateY(0);
             }
             to {
                 opacity: 0;
                 transform: translateY(-10px);
             }
         }

         .success-message {
             position: fixed;
             bottom: 2rem;
             left: 50%;
             transform: translateX(-50%);
             background-color: #10B981;
             color: white;
             padding: 1rem 1.5rem;
             border-radius: 8px;
             box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
             font-weight: 500;
             z-index: 1000;
             animation: slideUp 0.3s ease;
         }

         @keyframes slideUp {
             from {
                 opacity: 0;
                 transform: translateX(-50%) translateY(20px);
             }
             to {
                 opacity: 1;
                 transform: translateX(-50%) translateY(0);
             }
         }

         @media (prefers-reduced-motion: reduce) {
             @keyframes fadeOut {
                 from { opacity: 1; }
                 to { opacity: 0; }
             }
             @keyframes slideUp {
                 from { opacity: 0; }
                 to { opacity: 1; }
             }
         }
     `;
